#include <ranges>
#include <print>

auto squares = std::views::iota(1)                 // unbounded sequence
             | std::views::transform([](int n) { return n * n; })
             | std::views::filter([](int n) { return n % 2 == 1; });

for (int n : squares | std::views::take(10)) {     // forces ten elements
    std::println("{}", n);
}

