#include <generator>
#include <ranges>

std::generator<long long> fib() {
    long long a = 0, b = 1;
    while (true) {
        co_yield a;                              // suspend per element
        std::swap(a, b);
        b += a;                                  // (a, b) <- (b, a + b)
    }
}

int main() {
    for (auto n : fib() | std::views::take(10)) std::println("{}", n);
}

template <class T> struct Lazy {
    std::function<T()> thunk;                  // element + rest, forced once
    mutable std::optional<T> value;
    std::shared_ptr<Lazy> rest;
    const T& force() const { return value ? *value : *(value = thunk()); }
};
